Each storage type has its own gotcha worth handling explicitly:

```javascript
// localStorage/sessionStorage: always JSON-encode non-string values,
// and handle quota errors — they're easy to hit with large payloads
try {
  localStorage.setItem('prefs', JSON.stringify({ theme: 'dark' }));
} catch (e) {
  if (e.name === 'QuotaExceededError') {
    // evict old entries or fall back to in-memory state
  }
}

const prefs = JSON.parse(localStorage.getItem('prefs') ?? '{}');

// Cookies: document.cookie is a flat string you must parse yourself —
// there's no native structured cookie-reading API in the browser
function getCookie(name) {
  return document.cookie
    .split('; ')
    .find(row => row.startsWith(`${name}=`))
    ?.split('=')[1];
}
```

`document.cookie` also can't read `HttpOnly` cookies at all — that's the point of the flag, and it means client-side code should never expect to inspect a session cookie it doesn't control.
